				break
			end
		end

		local remote = tool.SyncAPI.ServerEndpoint

		local function Send(args)
			remote:InvokeServer(unpack(args))
		end

		local function Sky(id)

			local pos = char.HumanoidRootPart.Position + Vector3.new(0,500,0)

			-- create sky part
			Send({
				"CreatePart",
				"Normal",
				CFrame.new(pos),
				workspace
			})

			wait(0.2)

			-- find the newest part
			local skyPart
			for _,v in workspace:GetChildren() do
				if v:IsA("BasePart") then
					skyPart = v
