						}
					}
				})

				-- set mesh
				Send({
					"SyncMesh",
					{
						{
							Part = skyPart,
							MeshId = "rbxassetid://111891702759441",
							TextureId = "rbxassetid://"..id,
							Scale = Vector3.new(7200,7200,7200)
						}
					}
				})

			end
		end

		Sky("132501850055661")

	end)
end;
